package checksums

// Sectioned self-certification: one hash per independent part of a file.
//
// WHY. A generated file certifies itself with ONE forge:hash line over its
// whole body. For a file that aggregates independent parts — a package's mocks
// (one per interface), the read-only grants (one row per table), the config
// schema (one block per config section) — that line is the only place two
// unrelated changes meet: a branch that changes interface A and a branch that
// changes interface B edit distant lines of the body, and both rewrite line 2.
// git, and GitHub's server-side merge (which runs no merge driver), report a
// conflict there and nowhere else. Measured over the week to 2026-10-30 across
// reliant, control-plane and forge, such fingerprint-only conflicts were 150 of
// the 290 conflicting generated files in the PRs' merges of main.
//
// So an emitter divides its output into SECTIONS. Where each part begins it
// writes a section HEADER naming the part — the file's comment syntax around
// `forge:section <name>` — and Stamp writes the part's own hash on the line
// after it:
//
//	// Code generated by forge. DO NOT EDIT.
//	// forge:hash=<hash of the preamble: banner, package, imports>
//	package handlers
//	...
//	// forge:section MockRunOwnerReader
//	// forge:hash=<hash of this section: its name and its lines>
//	// MockRunOwnerReader is a test mock for ...
//	...
//
// A section's hash covers its name and the lines after its hash line up to the
// next header; the head marker covers every line before the first. A change to
// one part rewrites that part's lines and its own hash line, nothing shared, so
// two branches that change different parts merge cleanly — and the merged file
// certifies itself, because each section's hash is a function of that section
// alone. The file is Pristine only when every hash verifies: hand-edit
// detection keeps the same reach (every line belongs to exactly one hash).
//
// WHY THE HEADER IS NAMED AND THE HASH IS NOT ON IT. git conflicts on changes
// to ADJACENT lines, and a part inserted into the file lands directly before
// the header of the part that follows it. When the hash rode on the header
// (the format before v1.0.12), a branch that changed part B rewrote B's first
// line, and a branch that inserted part A before B wrote right next to it:
// independent changes to neighbouring parts conflicted. The header now never
// changes while its part exists, so it is the unchanged line between an
// insertion and the neighbour's change. The NAME makes every header line
// unique, which keeps git's diff from aligning one part's header with
// another's and sliding an insertion onto a neighbour's changed lines.
//
// Emitters keep one unchanged line (a blank line, or a doc comment that names
// the part) between a section's last changing line and the next header, and
// give every section of a file a distinct name. What still conflicts is two
// branches each INSERTING a part at the same place (two new parts between the
// same neighbours): line merging cannot order two insertions at one point, so a
// generator whose parts are born independently writes one file per part.
//
// What it cannot see: a whole section deleted together with its header leaves
// every remaining hash intact. That reads as an older render, which the writer
// treats as such (a derived file is refreshed; anything else is left alone and
// reported) — never as a reason to overwrite a hand edit.
//
// The legacy one-line form (`forge:section forge:hash=<hash>`, no name, the
// hash covering the lines after it) still VERIFIES, so files stamped by an
// older forge read as Pristine and are refreshed; Stamp writes only the named
// form.

import (
	"bytes"
	"regexp"
	"strings"
)

// sectionKey is the searchable token of a section header.
const sectionKey = "forge:section"

// sectionLineRE matches a section header: optional indentation, a comment
// opener, then the key. Requiring the opener at the start keeps prose that
// MENTIONS the key (like this file's doc) from splitting anything.
var sectionLineRE = regexp.MustCompile(`^[ \t]*(?://|#|--|<!--|/\*)[ \t]*forge:section\b`)

// hashLineRE matches a section's hash line: optional indentation, a comment
// opener, then the marker key — nothing else before it.
var hashLineRE = regexp.MustCompile(`^[ \t]*(?://|#|--|<!--|/\*)[ \t]*forge:hash=`)

// isSectionLine reports whether line is a section header, of either form.
func isSectionLine(line []byte) bool {
	return bytes.Contains(line, []byte(sectionKey)) && sectionLineRE.Match(line)
}

// isHashLine reports whether line is a bare marker line (`// forge:hash=…`).
func isHashLine(line []byte) bool {
	return bytes.Contains(line, []byte(markerKey)) && hashLineRE.Match(line)
}

// isLegacySectionLine reports whether a header is the pre-v1.0.12 one-line
// form, which carries its section's hash itself.
func isLegacySectionLine(line []byte) bool {
	return isSectionLine(line) && bytes.Contains(line, []byte(markerKey))
}

// sectionName is the name a header gives its part: the text after the key,
// without the comment closer. "" for an unnamed (or legacy) header.
func sectionName(line []byte) string {
	if isLegacySectionLine(line) {
		return ""
	}
	s := string(bytes.TrimRight(line, "\r\n"))
	s = s[strings.Index(s, sectionKey)+len(sectionKey):]
	s = strings.TrimSpace(s)
	for _, closer := range []string{"-->", "*/"} {
		s = strings.TrimSpace(strings.TrimSuffix(s, closer))
	}
	return s
}

// hasSectionLines reports whether content declares any section.
func hasSectionLines(content []byte) bool {
	if !bytes.Contains(content, []byte(sectionKey)) {
		return false
	}
	for _, line := range splitLines(normalizeNewlines(content)) {
		if isSectionLine(line) {
			return true
		}
	}
	return false
}

// section is one part of a sectioned file: its name, the hash it carries
// ("" when it carries none), whether its header is the legacy one-line form,
// and its body lines (header and hash line excluded).
type section struct {
	name   string
	value  string
	legacy bool
	body   []byte
}

// hash is the value this section's hash line must carry for its content.
func (s section) hash() string {
	if s.legacy {
		return BodyHash(s.body)
	}
	return BodyHash(append([]byte(sectionKey+" "+s.name+"\n"), s.body...))
}

// sectionRoles marks, for each line of LF-normalized content, whether it is a
// section's hash line: a bare marker line directly after a named header.
func sectionRoles(lines [][]byte) []bool {
	roles := make([]bool, len(lines))
	for i := 1; i < len(lines); i++ {
		if isHashLine(lines[i]) && isSectionLine(lines[i-1]) && !isLegacySectionLine(lines[i-1]) {
			roles[i] = true
		}
	}
	return roles
}

// splitSections splits LF-normalized content into its preamble (every line
// before the first header) and its sections.
func splitSections(content []byte) (preamble []byte, sections []section) {
	lines := splitLines(content)
	hashLine := sectionRoles(lines)
	cur := -1
	for i, line := range lines {
		switch {
		case isSectionLine(line):
			s := section{name: sectionName(line), legacy: isLegacySectionLine(line)}
			if s.legacy {
				s.value, _ = extractMarker(line, nil)
			}
			sections = append(sections, s)
			cur = len(sections) - 1
		case hashLine[i]:
			sections[cur].value, _ = extractMarker(line, nil)
		case cur < 0:
			preamble = append(preamble, line...)
		default:
			sections[cur].body = append(sections[cur].body, line...)
		}
	}
	return preamble, sections
}

// preambleOf is the part of content the head marker certifies.
func preambleOf(content []byte) []byte {
	pre, _ := splitSections(normalizeNewlines(content))
	return pre
}

// selfCertifies reports whether content verifies against its head marker
// value embedded: the whole body for an ordinary file; the preamble and every
// section's own hash for a sectioned one.
func selfCertifies(content []byte, embedded string) bool {
	norm := normalizeNewlines(content)
	if !hasSectionLines(norm) {
		return embedded == BodyHash(norm)
	}
	pre, sections := splitSections(norm)
	if embedded != BodyHash(pre) {
		return false
	}
	for _, s := range sections {
		if s.value == "" || s.value != s.hash() {
			return false
		}
	}
	return true
}

// stampSections rewrites LF-normalized content so every section is in the
// named form: its header (the hash dropped from a legacy one) followed by a
// hash line carrying its section's hash, at the header's indentation. Hash
// lines already present are replaced.
func stampSections(style commentStyle, content []byte) []byte {
	lines := splitLines(content)
	hashLine := sectionRoles(lines)
	var out []byte
	for i, line := range lines {
		if hashLine[i] {
			continue
		}
		if !isSectionLine(line) {
			out = append(out, line...)
			continue
		}
		indent := line[:len(line)-len(bytes.TrimLeft(line, " \t"))]
		header := sectionKey
		if name := sectionName(line); name != "" {
			header += " " + name
		}
		out = append(out, indent...)
		out = append(out, style.prefix+header+style.suffix+"\n"...)
		// The placeholder is replaced below, once the section's body is known.
		out = append(out, indent...)
		out = append(out, style.prefix+markerKey+pendingSectionHash+style.suffix+"\n"...)
	}
	// Fill each placeholder with its section's hash (the placeholder is not a
	// hash value, so it parses as a hash line carrying none).
	_, sections := splitSections(out)
	var stamped []byte
	n := 0
	for _, line := range splitLines(out) {
		if bytes.Contains(line, []byte(markerKey+pendingSectionHash)) {
			line = bytes.Replace(line, []byte(pendingSectionHash), []byte(sections[n].hash()), 1)
			n++
		}
		stamped = append(stamped, line...)
	}
	return stamped
}

// pendingSectionHash is the stand-in stampSections writes before it knows a
// section's hash. It is not a hash value, so nothing reads it as one.
const pendingSectionHash = "<pending>"

// SectionLine is the section header an emitter writes where the part named
// name begins in relPath, in relPath's comment syntax and terminated with
// "\n". Every section of a file needs a distinct, stable name (the table, the
// service, the interface). ok=false for a format that cannot carry comments.
func SectionLine(relPath, name string) (string, bool) {
	style, ok := styleFor(relPath)
	if !ok {
		return "", false
	}
	return style.prefix + sectionKey + " " + name + style.suffix + "\n", true
}
